INSERT INTO `site_settings` VALUES (1,'site_title','German Language Courses - Mega Guna Talent','branding','text','2026-10-11 10:23:16','2026-10-11 10:23:16'),(2,'site_tagline','Master the German language with native-speaking certified instructors','branding','text','2026-10-11 10:23:16','2026-10-11 10:23:16'),(3,'contact_email','info@megagunatalent.com','branding','text','2026-10-11 10:23:16','2026-10-11 10:23:16'),(4,'contact_phone','+62 813 2778 8498','branding','text','2026-10-11 10:23:16','2026-10-12 00:26:55'),(5,'contact_address','Jln Boulevard Raya A1 No. 16 Villa Galaxy RT. 001/019 Jaka Setia, Bekasi Selatan - Kota Bekasi','branding','text','2026-10-11 10:23:16','2026-10-11 22:01:28'),(6,'social_whatsapp','https://wa.me/6281327788498','branding','text','2026-10-11 10:23:16','2026-10-12 00:26:54'),(7,'social_instagram','https://instagram.com/megagunatalent','branding','text','2026-10-11 10:23:16','2026-10-11 10:23:16'),(8,'social_facebook','https://facebook.com/megagunatalent','branding','text','2026-10-11 10:23:16','2026-10-11 10:23:16'),(9,'social_linkedin','https://linkedin.com/company/megagunatalent','branding','text','2026-10-11 10:23:16','2026-10-11 10:23:16'),(10,'hero_badge_text','Lembaga Kursus Resmi & Mitra Persiapan Ausbildung Jerman','hero','text','2026-10-11 10:23:16','2026-10-11 22:01:28'),(11,'hero_title_line1','Kuasai Bahasa Jerman','hero','text','2026-10-11 10:23:16','2026-10-11 22:01:29'),(12,'hero_title_line2','Wujudkan Karier & Studi Impian','hero','text','2026-10-11 10:23:16','2026-10-11 22:01:29'),(13,'hero_subtitle','Bimbingan intensif dari level A1 hingga C1 bersama pengajar tersertifikasi berstandar Goethe-Institut.','hero','textarea','2026-10-11 10:23:16','2026-10-11 22:01:29'),(14,'hero_primary_btn_text','Daftar Sekarang','hero','text','2026-10-11 10:23:16','2026-10-11 22:01:29'),(15,'hero_primary_btn_url','#enroll','hero','text','2026-10-11 10:23:16','2026-10-11 10:23:16'),(16,'hero_secondary_btn_text','Pelajari Program','hero','text','2026-10-11 10:23:16','2026-10-11 22:01:29'),(17,'hero_secondary_btn_url','#programs','hero','text','2026-10-11 10:23:16','2026-10-11 10:23:16'),(18,'hero_stat_1_val','98%','hero','text','2026-10-11 10:23:16','2026-10-11 10:23:16'),(19,'hero_stat_1_lbl','Kelulusan Goethe-Zertifikat','hero','text','2026-10-11 10:23:16','2026-10-11 22:01:29'),(20,'hero_stat_2_val','1,500+','hero','text','2026-10-11 10:23:16','2026-10-11 10:23:16'),(21,'hero_stat_2_lbl','Alumni Studi & Ausbildung','hero','text','2026-10-11 10:23:16','2026-10-11 22:01:29'),(22,'hero_stat_3_val','100%','hero','text','2026-10-11 10:23:16','2026-10-11 10:23:16'),(23,'hero_stat_3_lbl','Pengajar Tersertifikasi','hero','text','2026-10-11 10:23:16','2026-10-11 22:01:29'),(24,'programs_badge','PROGRAM UNGGULAN KAMI','programs','text','2026-10-11 10:23:16','2026-10-11 22:01:29'),(25,'programs_title','Program Kursus & Jalur Persiapan','programs','text','2026-10-11 10:23:16','2026-10-11 22:01:29'),(26,'programs_subtitle','Kurikulum terstruktur dirancang sistematis dari fondasi percakapan hingga kemandirian bahasa untuk studi dan karier profesional di Jerman.','programs','textarea','2026-10-11 10:23:16','2026-10-11 22:01:29'),(27,'cta_badge','Mulai Perjalanan Anda','cta','text','2026-10-11 10:23:16','2026-10-11 22:17:12'),(28,'cta_title','Raih Target Bahasa Jerman Anda Bersama Kami','cta','text','2026-10-11 10:23:16','2026-10-11 22:17:13'),(29,'cta_subtitle','Kami membantu mewujudkan cita-cita studi, karier, dan Ausbildung Anda di Jerman melalui kurikulum terstruktur dan bimbingan mentor berpengalaman.','cta','textarea','2026-10-11 10:23:16','2026-10-11 22:17:13'),(30,'cta_button_text','Hubungi Kami & Daftar Sekarang','cta','text','2026-10-11 10:23:16','2026-10-11 22:17:13'),(31,'cta_button_url','#enroll','cta','text','2026-10-11 10:23:16','2026-10-11 10:23:16'),(32,'footer_about','LPK Mega Guna Talent adalah lembaga pelatihan kerja dan kursus bahasa Jerman resmi berstandar internasional CEFR dan SKKNI, mempersiapkan calon talenta andal untuk Ausbildung, karier, dan studi di Jerman.','footer','textarea','2026-10-11 10:23:16','2026-10-11 22:17:13'),(33,'footer_copyright','© 2026 LPK Mega Guna Talent. Hak Cipta Dilindungi Undang-Undang.','footer','text','2026-10-11 10:23:16','2026-10-11 22:17:13'),(34,'theme_color_primary','#2C0B1E','colors','text','2026-10-11 10:23:16','2026-10-11 10:23:16'),(35,'theme_color_gold','#E2B842','colors','text','2026-10-11 10:23:16','2026-10-11 10:23:16'),(36,'theme_color_gold_hover','#CFA230','colors','text','2026-10-11 10:23:16','2026-10-11 10:23:16'),(37,'program_1_title','Beginner','programs','text','2026-10-11 10:45:19','2026-10-11 10:45:19'),(38,'program_1_desc','Focus on practical communication skills for travelers and those new to the language.','programs','textarea','2026-10-11 10:45:19','2026-10-11 22:01:29'),(39,'program_2_title','Intermediate','programs','text','2026-10-11 10:45:19','2026-10-11 10:45:19'),(40,'program_2_desc','Building upon basic grammar, expanding vocabulary, and developing conversational fluency.','programs','textarea','2026-10-11 10:45:19','2026-10-11 22:01:29'),(41,'program_3_title','Advanced','programs','text','2026-10-11 10:45:19','2026-10-11 10:45:19'),(42,'program_3_desc','Tailored for those needing German in their careers, focusing on business or technical German.','programs','textarea','2026-10-11 10:45:19','2026-10-11 22:01:29'),(43,'site_logo','/storage/uploads/branding/RmBPxc5BBlRSGCODz4C3snEcC1BKc4rPKR5Df4I5.png','branding','image','2026-10-11 21:13:13','2026-10-11 21:18:55'),(44,'about_hero_badge','LPK Resmi Kemnaker RI • SKKNI & Goethe-Institut Standard','about','text','2026-10-11 21:13:13','2026-10-11 21:13:13'),(45,'about_hero_title','Membangun Generasi Kompeten & Siap Berkarier Global di Jerman','about','text','2026-10-11 21:13:13','2026-10-11 21:13:13'),(46,'about_hero_subtitle','LPK Mega Guna Talent adalah Lembaga Pelatihan Kerja terakreditasi yang berdedikasi menempa talenta muda Indonesia dengan penguasaan bahasa Jerman berstandar internasional, penguatan etos kerja profesional, dan fasilitas pembelajaran modern.','about','textarea','2026-10-11 21:13:13','2026-10-11 22:01:28'),(47,'about_visi','Menjadi Lembaga Pelatihan Kerja Yang Terdepan Dalam Membangun SDM Kompeten Sesuai Dengan Standar Kompetensi Kerja Nasional dan Internasional','about','textarea','2026-10-11 21:13:13','2026-10-11 22:01:28'),(48,'about_operating_hours','Senin - Sabtu: 08:30 - 17:00 WIB','about','text','2026-10-11 21:13:13','2026-10-11 21:13:13'),(49,'program_beginner_title','Beginner German Program','programs','text','2026-10-11 21:13:13','2026-10-11 21:13:13'),(50,'program_beginner_level','A1 - A2 (CEFR)','programs','text','2026-10-11 21:13:13','2026-10-11 21:13:13'),(51,'program_beginner_badge','Fondasi & Percakapan Harian','programs','text','2026-10-11 21:13:13','2026-10-11 21:13:13'),(52,'program_beginner_tagline','Kuasai Dasar Bahasa Jerman dari Nol Hingga Mampu Berkomunikasi Sehari-hari dan Lulus Sertifikasi Goethe A1/A2.','programs','text','2026-10-11 21:13:13','2026-10-11 21:13:13'),(53,'program_beginner_description','Program Beginner dirancang khusus bagi peserta yang belum pernah mempelajari bahasa Jerman sama sekali. Menggunakan metode pembelajaran interaktif berbasis SKKNI dan standar Goethe-Institut, peserta akan dibimbing mulai dari pelafalan presisi (Aussprache), kosakata esensial, struktur tata bahasa dasar (Akkusativ & Dativ), hingga simulasi percakapan nyata untuk kehidupan sehari-hari, perjalanan, dan persiapan awal studi di Jerman.','programs','textarea','2026-10-11 21:13:13','2026-10-11 22:01:29'),(54,'program_beginner_duration','10 - 12 Minggu','programs','text','2026-10-11 21:13:13','2026-10-11 21:13:13'),(55,'program_beginner_total_hours','160 Jam Pembelajaran Intensif','programs','text','2026-10-11 21:13:14','2026-10-11 21:13:14'),(56,'program_beginner_class_size','Maksimal 15 Siswa / Kelas','programs','text','2026-10-11 21:13:14','2026-10-11 21:13:14'),(57,'program_beginner_schedule','Senin - Jumat (09:00 - 13:00 WIB) / Pilihan Kelas Malam','programs','text','2026-10-11 21:13:14','2026-10-11 21:13:14'),(58,'program_beginner_target_exam','Goethe-Zertifikat A1 & A2','programs','text','2026-10-11 21:13:14','2026-10-11 21:13:14'),(59,'program_beginner_career_path','Lulusan level ini memiliki pondasi kuat untuk melanjutkan ke level Intermediate B1 (syarat utama Ausbildung), serta memenuhi syarat administratif dasar program Au Pair dan visa tertentu ke Jerman.','programs','text','2026-10-11 21:13:14','2026-10-11 21:13:14'),(60,'program_intermediate_title','Intermediate German Program','programs','text','2026-10-11 21:13:14','2026-10-11 21:13:14'),(61,'program_intermediate_level','B1 (CEFR)','programs','text','2026-10-11 21:13:14','2026-10-11 21:13:14'),(62,'program_intermediate_badge','Pintu Gerbang Utama Ausbildung Jerman','programs','text','2026-10-11 21:13:14','2026-10-11 21:13:14'),(63,'program_intermediate_tagline','Kunci Kelulusan Goethe-Zertifikat B1 Sebagai Syarat Mutlak Visa Ausbildung, Studi Vokasi, dan Karier di Jerman.','programs','text','2026-10-11 21:13:14','2026-10-11 21:13:14'),(64,'program_intermediate_description','Program Intermediate difokuskan untuk mencapai tingkat kemandirian berbahasa Jerman (Selbstständige Sprachverwendung). Level B1 adalah syarat wajib paling krusial bagi calon peserta program Ausbildung (perhotelan, keperawatan/Pflege, teknik/Mechatronik, gastronomi, dll.) di Jerman. Di level ini, peserta dilatih berdiskusi, memahami teks berita, menyusun argumentasi formal, serta menguasai struktur gramatikal lanjutan seperti kalimat pasif (Passiv), Konjunktiv II, dan klausa bawahan (Nebensätze).','programs','textarea','2026-10-11 21:13:14','2026-10-11 22:01:29'),(65,'program_intermediate_duration','12 Minggu','programs','text','2026-10-11 21:13:14','2026-10-11 21:13:14'),(66,'program_intermediate_total_hours','180 Jam Pembelajaran Intensif','programs','text','2026-10-11 21:13:14','2026-10-11 21:13:14'),(67,'program_intermediate_class_size','Maksimal 15 Siswa / Kelas','programs','text','2026-10-11 21:13:14','2026-10-11 21:13:14'),(68,'program_intermediate_schedule','Senin - Jumat (08:30 - 13:00 WIB)','programs','text','2026-10-11 21:13:14','2026-10-11 21:13:14'),(69,'program_intermediate_target_exam','Goethe-Zertifikat B1 (4 Modul)','programs','text','2026-10-11 21:13:14','2026-10-11 21:13:14'),(70,'program_intermediate_career_path','Sertifikat Goethe B1 adalah dokumen resmi utama yang diakui Kedutaan Besar Jerman di Jakarta untuk penerbitan visa Ausbildung, visa mencari pelatihan kerja, dan visa studi persiapan.','programs','text','2026-10-11 21:13:14','2026-10-11 21:13:14'),(71,'program_advanced_title','Advanced German Program','programs','text','2026-10-11 21:13:14','2026-10-11 21:13:14'),(72,'program_advanced_level','B2 - C1 (CEFR)','programs','text','2026-10-11 21:13:14','2026-10-11 21:13:14'),(73,'program_advanced_badge','Profisiensi Karier & Akademik','programs','text','2026-10-11 21:13:14','2026-10-11 21:13:14'),(74,'program_advanced_tagline','Kecakapan Bahasa Tingkat Tinggi untuk Jalur Karier Profesional, Bahasa Khusus (Fachsprache), dan Studi Universitas di Jerman.','programs','text','2026-10-11 21:13:14','2026-10-11 21:13:14'),(75,'program_advanced_description','Program Advanced dirancang untuk profesional, dokter, perawat ahli, insinyur, dan calon mahasiswa master/doktoral yang memerlukan kemahiran bahasa Jerman tingkat lanjut. Fokus pembelajaran mencakup bahasa teknis dan bisnis (Wirtschaftsdeutsch & Fachsprache), retorika presentasi, penulisan laporan ilmiah, negosiasi kontrak, serta pemahaman mendalam tentang teks kompleks abstrak dan teknis.','programs','textarea','2026-10-11 21:13:14','2026-10-11 22:01:29'),(76,'program_advanced_duration','12 - 14 Minggu','programs','text','2026-10-11 21:13:14','2026-10-11 21:13:14'),(77,'program_advanced_total_hours','200 Jam Pembelajaran Intensif','programs','text','2026-10-11 21:13:14','2026-10-11 21:13:14'),(78,'program_advanced_class_size','Maksimal 12 Siswa / Kelas (Fokus & Presisi)','programs','text','2026-10-11 21:13:14','2026-10-11 21:13:14'),(79,'program_advanced_schedule','Senin - Jumat / Kelas Spesialisasi Fleksibel','programs','text','2026-10-11 21:13:14','2026-10-11 21:13:14'),(80,'program_advanced_target_exam','Goethe-Zertifikat B2/C1 & TestDaF','programs','text','2026-10-11 21:13:14','2026-10-11 21:13:14'),(81,'program_advanced_career_path','Sertifikasi B2/C1 membuka akses langsung ke pasar kerja profesional berpenghasilan tinggi di Jerman, izin praktik profesi kesehatan, dan penerimaan universitas negeri ternama di Jerman.','programs','text','2026-10-11 21:13:14','2026-10-11 21:13:14'),(82,'about_hero_badge_en','Official Vocational Training Institute • SKKNI & Goethe Standard','about','text','2026-10-11 21:18:55','2026-10-11 22:01:28'),(83,'about_hero_badge_de','Anerkanntes Berufsbildungszentrum • Goethe-Institut Standard','about','text','2026-10-11 21:18:55','2026-10-11 22:01:28'),(84,'about_hero_title_en','Empowering Competent Talents for Global Careers in Germany','about','text','2026-10-11 21:18:55','2026-10-11 22:01:28'),(85,'about_hero_title_de','Kompetente Fachkräfte für erfolgreiche Karrieren in Deutschland','about','text','2026-10-11 21:18:55','2026-10-11 22:01:28'),(86,'about_hero_subtitle_en','LPK Mega Guna Talent is an accredited vocational institute committed to forging Indonesian youth through international-standard German language mastery, solid professional work ethics, and modern immersive learning environments.','about','textarea','2026-10-11 21:18:55','2026-10-11 22:01:28'),(87,'about_hero_subtitle_de','LPK Mega Guna Talent ist eine akkreditierte Ausbildungsstätte, die junge indonesische Talente gezielt auf Ausbildung, Studium und qualifizierte Berufe in Deutschland vorbereitet – mit intensivem Sprachunterricht und praxisnaher Arbeitskultur.','about','textarea','2026-10-11 21:18:55','2026-10-11 22:01:28'),(88,'about_visi_en','To be the foremost vocational training institute cultivating globally competitive human resources aligned with national and international professional standards.','about','textarea','2026-10-11 21:18:55','2026-10-11 22:01:28'),(89,'about_visi_de','Ein führendes Institut für berufliche Bildung zu sein, das hochqualifizierte Fachkräfte nach nationalen und internationalen Kompetenzstandards ausbildet.','about','textarea','2026-10-11 21:18:55','2026-10-11 22:01:28'),(90,'hero_badge_text_en','Official German Language Center & Ausbildung Partner','hero','text','2026-10-11 21:18:55','2026-10-11 22:01:28'),(91,'hero_badge_text_de','Offizielles Deutsches Sprachzentrum & Ausbildungspartner','hero','text','2026-10-11 21:18:55','2026-10-11 22:01:29'),(92,'hero_title_line1_en','Speak German With Confidence','hero','text','2026-10-11 21:18:55','2026-10-11 22:01:29'),(93,'hero_title_line1_de','Deutsch sprechen mit Selbstvertrauen','hero','text','2026-10-11 21:18:55','2026-10-11 22:01:29'),(94,'hero_title_line2_en','Unlock Your Career & Study in Germany','hero','text','2026-10-11 21:18:55','2026-10-11 22:01:29'),(95,'hero_title_line2_de','Ihre Zukunft in Deutschland starten','hero','text','2026-10-11 21:18:55','2026-10-11 22:01:29'),(96,'hero_subtitle_en','Engaging German courses for all levels. Learn German with flexible programs, experienced native tutors, and real-world conversations.','hero','textarea','2026-10-11 21:18:55','2026-10-11 22:01:29'),(97,'hero_subtitle_de','Interaktive Deutschkurse für alle Niveaustufen von A1 bis C1 mit zertifizierten Dozenten und Goethe-Zertifikat Vorbereitung.','hero','textarea','2026-10-11 21:18:55','2026-10-11 22:01:29'),(98,'hero_primary_btn_text_en','Enroll Now','hero','text','2026-10-11 21:18:55','2026-10-11 22:01:29'),(99,'hero_primary_btn_text_de','Jetzt anmelden','hero','text','2026-10-11 21:18:55','2026-10-11 22:01:29'),(100,'program_beginner_title_en','Beginner German Program (A1 - A2)','programs','text','2026-10-11 21:18:56','2026-10-11 22:01:29'),(101,'program_beginner_title_de','Deutsch Grundstufe (A1 - A2)','programs','text','2026-10-11 21:18:56','2026-10-11 22:01:29'),(102,'program_beginner_tagline_en','Master German fundamentals from scratch to fluent everyday conversation and certified Goethe A1/A2 qualification.','programs','text','2026-10-11 21:18:56','2026-10-11 22:01:29'),(103,'program_beginner_tagline_de','Deutsche Grundlagen von Null auf lernen: Sichere Alltagskommunikation und erfolgreicher Goethe-A1/A2-Abschluss.','programs','text','2026-10-11 21:18:56','2026-10-11 22:01:29'),(104,'program_beginner_description_en','Tailored for learners with zero prior knowledge. Guided by certified instructors using CEFR benchmarks, you master proper pronunciation, essential vocabulary, sentence syntax (Accusative/Dative), and real-life dialogue simulations for living and studying in Germany.','programs','textarea','2026-10-11 21:18:56','2026-10-11 22:01:29'),(105,'program_beginner_description_de','Speziell für Anfänger ohne Vorkenntnisse entwickelt. Schrittweise Vermittlung von exakter Aussprache, Grundwortschatz, Grammatikstrukturen und lebendigen Dialogübungen nach offiziellen Standards des Goethe-Instituts.','programs','textarea','2026-10-11 21:18:56','2026-10-11 22:01:29'),(106,'program_beginner_career_path_en','Provides the indispensable prerequisite foundation for Intermediate B1 (Ausbildung entry), Au Pair placements, and early academic preparation.','programs','text','2026-10-11 21:18:56','2026-10-11 22:01:29'),(107,'program_beginner_career_path_de','Solide Basis für den direkten Übergang zur Mittelstufe B1 sowie Erfüllung der Sprachanforderungen für Au-Pair und Orientierungsvisa.','programs','text','2026-10-11 21:18:56','2026-10-11 22:01:29'),(108,'program_intermediate_title_en','Intermediate German Program (B1)','programs','text','2026-10-11 21:18:56','2026-10-11 22:01:29'),(109,'program_intermediate_title_de','Deutsch Mittelstufe (B1)','programs','text','2026-10-11 21:18:56','2026-10-11 22:01:29'),(110,'program_intermediate_tagline_en','Your definitive stepping stone to Goethe B1 certification, mandatory for vocational Ausbildung and work visas in Germany.','programs','text','2026-10-11 21:18:56','2026-10-11 22:01:29'),(111,'program_intermediate_tagline_de','Der entscheidende Meilenstein zum Goethe-Zertifikat B1 – Pflichtvoraussetzung für die duale Ausbildung in Deutschland.','programs','text','2026-10-11 21:18:56','2026-10-11 22:01:29'),(112,'program_intermediate_description_en','Focused on independent language proficiency (CEFR B1). Trainees master complex grammar (Passive voice, Subjunctive II, subordinate clauses), workplace terminology, interview readiness, and intensive drill in all 4 exam modules (Reading, Listening, Writing, Speaking).','programs','textarea','2026-10-11 21:18:56','2026-10-11 22:01:29'),(113,'program_intermediate_description_de','Fokus auf selbstständige Sprachverwendung. Umfassende Vorbereitung auf alle vier Prüfungsmodule (Lesen, Hören, Schreiben, Sprechen) mit berufsbezogener Fachsprache für Pflege, Gastronomie und Handwerk.','programs','textarea','2026-10-11 21:18:56','2026-10-11 22:01:29'),(114,'program_intermediate_career_path_en','The official key required by the German Embassy for issuing dual vocational training (Ausbildung) visas in healthcare, engineering, IT, and hospitality.','programs','text','2026-10-11 21:18:56','2026-10-11 22:01:29'),(115,'program_intermediate_career_path_de','Vollständige Erfüllung der Visakriterien der Deutschen Botschaft für die Einreise zur dualen Ausbildung und Fachkräfteweiterbildung.','programs','text','2026-10-11 21:18:56','2026-10-11 22:01:29'),(116,'program_advanced_title_en','Advanced German Program (B2 - C1)','programs','text','2026-10-11 21:18:56','2026-10-11 22:01:29'),(117,'program_advanced_title_de','Deutsch Oberstufe (B2 - C1)','programs','text','2026-10-11 21:18:56','2026-10-11 22:01:29'),(118,'program_advanced_tagline_en','Superior professional fluency, specialized technical German (Fachsprache), and direct entrance to German universities.','programs','text','2026-10-11 21:18:56','2026-10-11 22:01:29'),(119,'program_advanced_tagline_de','Höchste Sprachkompetenz für Fachkräfte, Mediziner, Wirtschaftsdeutsch und universitäres Studium in Deutschland.','programs','text','2026-10-11 21:18:56','2026-10-11 22:01:29'),(120,'program_advanced_description_en','Designed for qualified doctors, nurses, engineers, and graduate researchers. Focuses on advanced discourse, technical academic writing, medical terminology, negotiation rhetoric, and rigorous TestDaF / Goethe B2-C1 preparation.','programs','textarea','2026-10-11 21:18:56','2026-10-11 22:01:29'),(121,'program_advanced_description_de','Gezielt konzipiert für Akademiker, Ärzte, Ingenieure und Masterstudierende. Schwerpunkte: Fachsprache, wissenschaftliches Schreiben, Verhandlungsführung und zielgerichtetes Training für TestDaF sowie Goethe B2/C1.','programs','textarea','2026-10-11 21:18:56','2026-10-11 22:01:29'),(122,'program_advanced_career_path_en','Unlocks high-salary professional employment in Germany, medical professional licensing (Approbation), and direct admission to German public universities.','programs','text','2026-10-11 21:18:56','2026-10-11 22:01:29'),(123,'program_advanced_career_path_de','Berechtigt zur ärztlichen Approbation, direkter Arbeitsaufnahme in deutschen Spitzenunternehmen sowie uneingeschränkter Hochschulzulassung.','programs','text','2026-10-11 21:18:56','2026-10-11 22:01:29'),(124,'site_favicon','/storage/uploads/branding/KC60rr6PcZjK1TayAdO18bkV31QUowSBqyfvBVBA.png','branding','image','2026-10-11 21:38:18','2026-10-11 21:38:18'),(125,'about_operating_hours_en','Monday - Saturday: 08:30 AM - 05:00 PM (WIB)','about','text','2026-10-11 22:01:28','2026-10-11 22:01:28'),(126,'about_operating_hours_de','Montag - Samstag: 08:30 - 17:00 Uhr (WIB)','about','text','2026-10-11 22:01:28','2026-10-11 22:01:28'),(127,'hero_secondary_btn_text_en','Explore Programs','hero','text'