1_desc_en','Practical foundational skills for beginners and travel readiness.','programs','textarea','2026-10-11 22:01:29','2026-10-11 22:01:29'),(144,'program_1_desc_de','Praktische Grundkenntnisse für Anfänger und Alltagssituationen.','programs','textarea','2026-10-11 22:01:29','2026-10-11 22:01:29'),(145,'program_2_title_en','Intermediate (B1)','programs','text','2026-10-11 22:01:29','2026-10-11 22:01:29'),(146,'program_2_title_de','Mittelstufe (B1)','programs','text','2026-10-11 22:01:29','2026-10-11 22:01:29'),(147,'program_2_desc_en','Independent language competence essential for Ausbildung vocational training.','programs','textarea','2026-10-11 22:01:29','2026-10-11 22:01:29'),(148,'program_2_desc_de','Selbstständige Sprachverwendung für Ausbildung und Berufsleben.','programs','textarea','2026-10-11 22:01:29','2026-10-11 22:01:29'),(149,'program_3_title_en','Advanced (B2 - C1)','programs','text','2026-10-11 22:01:29','2026-10-11 22:01:29'),(150,'program_3_title_de','Oberstufe (B2 - C1)','programs','text','2026-10-11 22:01:29','2026-10-11 22:01:29'),(151,'program_3_desc_en','Specialized technical and business German for university and medical careers.','programs','textarea','2026-10-11 22:01:29','2026-10-11 22:01:29'),(152,'program_3_desc_de','Fach- und Wirtschaftssprache für Akademiker, Ärzte und Ingenieure.','programs','textarea','2026-10-11 22:01:29','2026-10-11 22:01:29'),(153,'cta_badge_en','Start Your Journey Today','cta','text','2026-10-11 22:17:13','2026-10-11 22:17:13'),(154,'cta_badge_de','Starten Sie Ihre Sprachreise','cta','text','2026-10-11 22:17:13','2026-10-11 22:17:13'),(155,'cta_title_en','Achieve Your German Language Goals','cta','text','2026-10-11 22:17:13','2026-10-11 22:17:13'),(156,'cta_title_de','Erreichen Sie Ihre Deutsch-Sprachziele','cta','text','2026-10-11 22:17:13','2026-10-11 22:17:13'),(157,'cta_subtitle_en','We help you achieve your language learning goals, whether for travel, work, or personal enrichment with certified tutors.','cta','textarea','2026-10-11 22:17:13','2026-10-11 22:17:13'),(158,'cta_subtitle_de','Wir unterstützen Sie beim Erreichen Ihrer Sprachziele für Ausbildung, Studium oder Beruf mit praxisnahem Unterricht und Goethe-Zertifikat Vorbereitung.','cta','textarea','2026-10-11 22:17:13','2026-10-11 22:17:13'),(159,'cta_button_text_en','Contact Us & Enroll Now','cta','text','2026-10-11 22:17:13','2026-10-11 22:17:13'),(160,'cta_button_text_de','Kontaktieren & Jetzt Anmelden','cta','text','2026-10-11 22:17:13','2026-10-11 22:17:13'),(161,'footer_about_en','LPK Mega Guna Talent is an official vocational training and German language institution adhering to CEFR & SKKNI standards, preparing talented candidates for Ausbildung, careers, and university studies in Germany.','footer','textarea','2026-10-11 22:17:13','2026-10-11 22:17:13'),(162,'footer_about_de','LPK Mega Guna Talent ist ein offizielles Berufsbildungs- und Sprachinstitut nach GER- und SKKNI-Standards zur Vorbereitung von Talenten auf Ausbildung, Beruf und Studium in Deutschland.','footer','textarea','2026-10-11 22:17:13','2026-10-11 22:17:13'),(163,'footer_copyright_en','© 2026 Mega Guna Talent. All Rights Reserved.','footer','text','2026-10-11 22:17:13','2026-10-11 22:17:13'),(164,'footer_copyright_de','© 2026 Mega Guna Talent. Alle Rechte vorbehalten.','footer','text','2026-10-11 22:17:13','2026-10-11 22:17:13'),(165,'about_metric_1_val','240+','about','text','2026-10-12 01:43:46','2026-10-12 01:43:46'),(166,'about_metric_1_val_en','240+','about','text','2026-10-12 01:43:46','2026-10-12 01:43:46'),(167,'about_metric_1_val_de','240+','about','text','2026-10-12 01:43:46','2026-10-12 01:43:46'),(168,'about_metric_1_lbl','Kapasitas Siswa / Tahun','about','text','2026-10-12 01:43:46','2026-10-12 01:43:46'),(169,'about_metric_1_lbl_en','Student Capacity / Year','about','text','2026-10-12 01:43:46','2026-10-12 01:43:46'),(170,'about_metric_1_lbl_de','Teilnehmerkapazität / Jahr','about','text','2026-10-12 01:43:46','2026-10-1